program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(seq):
        result = []
        i = 0
        while i < len(seq):
            if seq[i] == bg:
                i += 1
                continue
            color = seq[i]
            j = i + 1
            while j < len(seq) and seq[j] == color:
                j += 1
            result.append((color, i, j))
            i = j
        return result

    # The bars occupy opposite borders and have equal color and length.
    candidates = []
    for axis, edge_a, edge_b in (
        ("lr", [grid[r][0] for r in range(h)], [grid[r][w-1] for r in range(h)]),
        ("tb", grid[0], grid[h-1]),
    ):
        for ca, a0, a1 in runs(edge_a):
            for cb, b0, b1 in runs(edge_b):
                if ca == cb and a1-a0 == b1-b0:
                    candidates.append((a1-a0, axis, ca, (a0, a1), (b0, b1)))
    if not candidates:
        return [row[:] for row in grid]
    _, axis, marker, seg_a, seg_b = max(candidates)
    out = [row[:] for row in grid]

    # Non-background, non-marker interior pixels select matching lanes in both bars.
    dots = []
    for r in range(1, h-1):
        for c in range(1, w-1):
            v = grid[r][c]
            if v != bg and v != marker:
                coord = r if axis == "lr" else c
                for seg in (seg_a, seg_b):
                    if seg[0] <= coord < seg[1]:
                        dots.append((r, c, v, coord-seg[0]))
                        break
    if not dots:
        return out

    lanes = {}
    for r, c, color, offset in dots:
        lanes.setdefault(offset, color)

    for offset, color in lanes.items():
        for seg, side in ((seg_a, 0), (seg_b, 1)):
            coord = seg[0] + offset
            if axis == "lr":
                r = coord
                c = 1 if side == 0 else w-2
                step = 1 if side == 0 else -1
                while 0 < c < w-1:
                    if grid[r][c] != bg and grid[r][c] != marker:
                        out[r][c] = 4
                        break
                    out[r][c] = color
                    c += step
            else:
                c = coord
                r = 1 if side == 0 else h-2
                step = 1 if side == 0 else -1
                while 0 < r < h-1:
                    if grid[r][c] != bg and grid[r][c] != marker:
                        out[r][c] = 4
                        break
                    out[r][c] = color
                    r += step

    # Dots that were not directly reached by a ray are still endpoints on their lanes.
    for r, c, _, _ in dots:
        out[r][c] = 4
    return out
'''
